edits.new:
/* Physical at[k*512+i]=A[i*512+k], using 4x4 NEON microtiles
   inside 32x32 tiles. Every input and output index is below 512. */
for (int row_block = 0; row_block < 512; row_block += 32) {
    for (int column_block = 0; column_block < 512; column_block += 32) {
        for (int row = row_block; row < row_block + 32; row += 4) {
            for (int column = column_block; column < column_block + 32; column += 4) {
                const float *input = A + (size_t)row * 512 + column;
                float *output = at + (size_t)column * 512 + row;
                float32x4_t row0 = vld1q_f32(input);
                float32x4_t row1 = vld1q_f32(input + 512);
                float32x4_t row2 = vld1q_f32(input + 1024);
                float32x4_t row3 = vld1q_f32(input + 1536);
                float32x4x2_t pair01 = vtrnq_f32(row0, row1);
                float32x4x2_t pair23 = vtrnq_f32(row2, row3);
                float32x4_t column0 = vcombine_f32(
                    vget_low_f32(pair01.val[0]), vget_low_f32(pair23.val[0]));
                float32x4_t column1 = vcombine_f32(
                    vget_low_f32(pair01.val[1]), vget_low_f32(pair23.val[1]));
                float32x4_t column2 = vcombine_f32(
                    vget_high_f32(pair01.val[0]), vget_high_f32(pair23.val[0]));
                float32x4_t column3 = vcombine_f32(
                    vget_high_f32(pair01.val[1]), vget_high_f32(pair23.val[1]));
                vst1q_f32(output, column0);
                vst1q_f32(output + 512, column1);
                vst1q_f32(output + 1024, column2);
                vst1q_f32(output + 1536, column3);
            }
        }
    }
}
parameters[10] = at;
sera_libxsmm_tb(parameters);
free(at);
